SHARH[1] = [
 ('غزلی ملمّع در آغاز دیوان', 'این غزل هفت بیت دارد و ملمّع است: مصرع نخست و مصرع پایانی عربی و باقی فارسی است. نخست‌آمدنش در چاپ‌ها از ترتیب الفبایی قافیه‌هاست که قزوینی و غنی خود برگزیده‌اند، چون به گفتهٔ آنان دست‌نویس‌ها نه در ترتیب غزل‌ها و نه در ترتیب بیت‌ها با هم ربطی ندارند؛ با این همه نخست‌بودنش دست‌کم به سدهٔ نهم می‌رسد: کاتبی نیشابوری (به نقل سودی) بر آن خرده گرفته و در تدوین نیساری از دست‌نویس‌های سدهٔ نهم نیز همین غزل نخستین است.', ['qg:۱', 'qg:چهل‌ویک (مقدمه)', 'su:۱', 'ni:۳۱']),
 ('افسانهٔ مصرعِ یزید', 'سودی نوشته است که مصرع نخست از قطعه‌ای منسوب به یزید بن معاویه است و حافظ آن را تضمین کرده، و از اعتراض شاعران و پاسخ‌های منظوم اهلی شیرازی و کاتبی یاد می‌کند. محمد قزوینی در مجلهٔ یادگار منابع کهن عربی را جست و نوشت که از این بیت منسوب به یزید «در هیچ جا نشانی و اثری و خبری» نیافته و حکایت «به کلی مجعول و ساختگی است»؛ به گمان او بیت عربی به تقلید از ملمّعی از سعدی ساخته شده است.', ['su:۱', 'محمد قزوینی، «تحقیق در اشعار حافظ: بعضی تضمین‌های حافظ»، یادگار، ش ۹، ۱۳۲۴']),
 ('پیر مغان، آفریدهٔ حافظ', 'بلندترین یادداشت خرمشاهی بر این غزل دربارهٔ «پیر مغان» است. به گفتهٔ او سند قاطعی از سرسپردگی حافظ به پیری معیّن در دست نیست و «اسطورهٔ پیرمغان ساختهٔ طبع حافظ است، همان‌طور که فی‌المثل رستم به یک معنی پروردهٔ طبع فردوسی است»؛ از قاسم غنی هم نقل می‌کند که نباید بیهوده دنبال ردپای تاریخی او بود.', ['kh:۹۶–۹۹']),
 ('شب تاریک و بیم موج', 'با آن‌که بیت «شب تاریک و بیم موج و گردابی چنین هایل» از مشهورترین بیت‌های دیوان است، خرمشاهی بر آن یادداشتی ندارد؛ مهدی نوریان در مستدرک همان کتاب این را یادآور شده است. سودی این بیت را شرح کرده است.', ['kh:۱۴۷۵', 'su:۱۳']),
 ('وزن و مثل‌ها', 'وزن غزل «مفاعیلن مفاعیلن مفاعیلن مفاعیلن» (هزج مثمّن سالم) است. چند مصرع آن مَثَل شده است، از جمله «که عشق آسان نمود اول ولی افتاد مشکل‌ها»، «شب تاریک و بیم موج» و «همه کارم ز خودکامی به بدنامی کشید آخر».', ['su:۱', 'سیروس شمیسا، آشنایی با عروض و قافیه، میترا، ۱۳۸۳، ص ۴۴', 'se:۱۷–۱۹']),
 ('نخستین غزلِ ترجمه‌شده', 'این غزل نخستین شعر حافظ است که به زبانی اروپایی رسید: مننسکی در دستور زبان ترکی (وین، ۱۶۸۰) آن را همراه شرح سودی به لاتین برگرداند؛ نخستین ترجمهٔ انگلیسی از جان ریچاردسون (۱۷۷۴) است.', ['F. Meninski, Grammatica Turcica, Vienna 1680, pp. 189–190', 'J. Richardson, A Specimen of Persian Poetry, 1774, pp. 3–6']),
]

SHARH[2] = [
 ('قافیهٔ مطلع: ایرادی که پس گرفته شد', 'سودی و جلالیان قافیهٔ «خراب / کجا» را در مطلع معیوب دانسته‌اند و خرمشاهی نیز در آغاز مدخلش نوشته بود «تا به کجا از نظر قافیه عیب دارد». اما در مستدرکِ حافظ‌نامه، در پاسخ به حسین معصومی که یادآور شد فارسیِ آن روزگار «نیم‌فتحه» داشته، خرمشاهی پذیرفت: «حق با ایشان است. به احتمال بسیار، در تلفظ حافظ و عصر حافظ تفاوتی بین این قافیه و قوافی سایر ابیات این غزل نبوده است.»', ['su:۱۸', 'ja', 'kh:۱۰۱', 'kh:۱۳۵۲']),
 ('صومعه در برابر دیر مغان', 'خرمشاهی «صومعه» را در شعر حافظ همان «خانقاه» و نقطهٔ مقابل «دیر مغان» می‌داند و برایش از دیوان شاهد می‌آورد. «خرقه» را نیز سه گونه می‌شمارد ــ خرقهٔ زاهد، خرقهٔ صوفی و خرقهٔ خود حافظ ــ و می‌گوید حافظ به هیچ‌یک نظر خوبی ندارد.', ['kh:۱۰۱–۱۰۴']),
 ('شمع آفتاب', 'خرمشاهی «شمع آفتاب» را اضافهٔ تشبیهی نمی‌داند و آن را «مشعل و شعلهٔ آفتاب» می‌خواند؛ مهدی نوریان در همان کتاب این را نمی‌پذیرد و آن را همان اضافهٔ تشبیهی می‌داند، چون در برابر پیه‌سوز شمع روشنایی برتر بوده است.', ['kh:۱۰۷', 'kh:۱۴۷۶']),
 ('«یاد خوشش باد»', 'ضمیرِ «ـش» در «بشد که یاد خوشش باد روزگار وصال» به «روزگار وصال» بازمی‌گردد که پس از آن آمده است («إضمار قبل از ذکر» به تعبیر جلالیان، «عود ضمیر به متأخر» به تعبیر نوریان): «روزگار وصال که یادش خوش باد، بشد.» سودی ماجرای بحثش بر سر همین ضمیر را با یک فارسی‌زبان در شرح خود آورده است.', ['ja', 'kh:۱۴۷۶', 'su:۲۰–۲۱']),
 ('خوانشی تاریخی', 'جلالیان غزل را از روزگار شاه شجاع می‌داند، هنگامی که شاه به ظاهر از حافظ فاصله گرفت، و «چاه در راه» بیت ششم را مشاوران دربار می‌خواند. این یک خوانش است، نه گزارشی مستند از تاریخ سرایش غزل.', ['ja']),
 ('مثل‌ها', 'مطلع غزل در فرهنگ‌های مثل به معنای «بیان تفاوت آشکار بین دو موضوع» آمده و بیت ششم («مبین به سیب زنخدان که چاه در راه است») به معنای این‌که «انسان نباید خطرها را فراموش کند».', ['se:۱۹–۲۰', 'zo:۴۸۲']),
]

SHARH[3] = [
 ('«ترک شیرازی» کیست؟', 'سودی می‌گوید شاعران فارسی معشوق را در بی‌رحمی و سنگدلی به ترکان مانند کرده و «ترک» خوانده‌اند، و از برخی شیرازیان نقل می‌کند که مراد ترکانی‌اند که از سپاه هلاکو در شیراز ماندند. خرمشاهی از محمد معین نقل می‌کند که چون غلامان و کنیزان ترک‌نژاد زیبا بودند، «ترک» به معنی معشوق زیباروی به کار رفت. واژهٔ «ترک» در فارسی جنسیت ندارد و مترجمان اروپایی معشوق را گاه زن و گاه مرد گرفته‌اند.', ['su:۲۴–۲۵', 'kh:۱۰۹']),
 ('خال هندو و آب رکن‌آباد', 'به گفتهٔ خرمشاهی «هندو» یعنی هندی و مراد از آن سیاه است؛ «هندو» در شعر حافظ به معنی غلام هم آمده، پس شاید بخشیدن سمرقند و بخارا «نه به خال خود بلکه به خال غلام او» مبالغه در احترام باشد. نهر رکن‌آباد را، به یادداشت قزوینی که خرمشاهی نقل کرده، رکن‌الدولهٔ دیلمی در سال ۳۳۸ کند و آبش به مصلّی و آرامگاه حافظ می‌رسد.', ['kh:۱۱۰', 'kh:۱۱۴']),
 ('دیدار با تیمور: حکایتی بی‌پایه', 'کهن‌ترین صورت شناخته‌شدهٔ حکایت دیدار تیمور و حافظ ــ که تیمور بر بخشیدن سمرقند و بخارا خرده می‌گیرد ــ در تذکرةالشعرای دولتشاه سمرقندی است (اینجنیتو آن را در انیس‌الناس، ۱۴۲۶ م، پیش‌تر می‌یابد). بیژن صمدی نشان داده که خود دولتشاه مرگ حافظ را ۷۹۴ و دیدار را ۷۹۵ آورده و منابع تاریخی آن روزگار از چنین دیداری یاد نکرده‌اند، و حکایت را «ساخته و پرداختهٔ دولتشاه» می‌داند. خرمشاهی یادآور می‌شود که تیمور یک بار در ۷۸۹ که حافظ زنده بود و بار دیگر در ۷۹۵ که درگذشته بود به شیراز آمد، و بیت ادعای مالکیت نیست: با داشتن آن ترک شیرازی طمعی به سمرقند و بخارا ندارم.', ['kh:۱۱۱', 'بیژن صمدی، «ملاقات ناممکن حافظ و تیمور لنگ»، کیهان اندیشه، ۱۳۷۰', 'D. Ingenito, “Hafez’s ‘Shirāzi Turk’: A Geopoetical Approach”, Iranian Studies, 2018']),
 ('مروارید‌های بی‌نظم؟', 'این غزل نخستین غزل حافظ است که به انگلیسی ترجمه شد (ویلیام جونز) و شناخته‌شده‌ترین شعر او در جهان انگلیسی‌زبان است. جونز در مقطع عبارت «like orient pearls at random strung» را افزود که در متن فارسی نیست، و همین بحثی دراز در غرب برانگیخت که آیا غزل حافظ یکپارچه است یا بیت‌هایی پراکنده: آربری آن را افزوده‌ای بدفرجام خواند، ویکنز در ساختار معناهای غزل یکپارچگی دید و بویس او را نقد کرد، و هیلمن آن را نمونهٔ ناپیوستگی دانست. پریچت یادآور می‌شود که چون ترتیب و شمار بیت‌ها در نسخه‌ها یکسان نیست، جویندگان یکپارچگی ناچارند با گزینش‌های ویرایشی خود همان شعری را بسازند که یکپارچه‌اش می‌بینند.', ['P. Loloi, “Hafez x. Translations of Hafez in English”, Encyclopaedia Iranica, 2002', 'F. W. Pritchett, “Orient Pearls Unstrung”, Edebiyât, 1993', 'G. M. Wickens, BSOAS, 1952', 'M. Boyce, “A Novel Interpretation of Hafiz”, BSOAS, 1953', 'M. C. Hillmann, “Hafez’s ‘Turk of Shiraz’ Again”, Iranian Studies, 1975']),
 ('مثل‌ها', 'پنج بیت از این غزل در فرهنگ‌های مثل آمده است، از جمله «فغان کاین لولیان شوخ»، «ز عشق ناتمام ما»، «اگر دشنام فرمایی» و «نصیحت گوش کن جانا».', ['se:۲۱–۲۴', 'zo:۵۴۶']),
]

SHARH[5] = [
 ('کشتی‌شکستگان یا کشتی‌نشستگان؟', 'بزرگ‌ترین اختلاف این غزل بر سر بیت دوم است. سودی و جلالیان «کشتی نشستگانیم» را درست می‌دانند؛ جلالیان استدلال می‌کند که نیروی کشتی در گذشته باد موافق بود و اگر کشتی شکسته باشد باد موافق «هیچ‌گونه معجزه‌یی» نمی‌کند. خرمشاهی در برابر «نشستگانیم» را «قرائت مرجوح» می‌نامد: کشتی‌نشستگان در حال عادی بیمی ندارند که ملتمسانه از باد یاری بخواهند، و مصرع پرهراس دوم «شکستگانیم» را تأیید می‌کند. در دستگاه نیساری «نشستگانیم» تنها یک گواه دارد و متن او، مانند حافظ به سعی سایه، «شکستگانیم» است.', ['ja:۱۴۲', 'su:۴۱', 'kh:۱۲۷', 'kh:۱۵۱۸', 'ni:۳۳', 'sa:۸۳']),
 ('باد شرطه', 'سودی معنای لغوی «شرطه» را در کتاب‌های لغت نیافت و گفت در کاربرد، باد موافق را شرطه گویند. خرمشاهی جامع‌ترین تحقیق را از قزوینی می‌داند: بادی که مساعد کشتی‌رانی باشد و کشتی را به سوی مقصد براند؛ و از غنی نقل می‌کند که شرطه عربی نیست و اصلش سانسکریت و هندی است. جلالیان نیز آن را از اصطلاحات دریانوردان اقیانوس هند می‌داند.', ['su:۴۱', 'kh:۱۲۷–۱۲۸', 'ja:۱۴۲']),
 ('بیت عربی و «تلخ‌وش»', 'بیت هشتم عربی است؛ نیساری ترجمه‌اش را چنین آورده: «شراب صبحگاهی را بیاور، بیدار شوید ای باده‌نوشان» و «گواراتر است برای ما و شیرین‌تر است از بوسهٔ دوشیزگان». خرمشاهی «هُبّوا» را «بیدار شوید، برخیزید» می‌داند و یادآور می‌شود که بیشتر نسخه‌ها همین را دارند. «تلخ‌وش» در بیت بعد به گفتهٔ او «تلخ‌گونه، تلخ‌مزه» است و او حدیث «امّ‌الخبائث» را از سیوطی نقل می‌کند.', ['ni:۳۳', 'kh:۱۲۹–۱۳۰']),
 ('پیوند با سعدی', 'جلالیان می‌نویسد مولوی، عماد فقیه، اوحدی و همام نیز در این وزن و قافیه غزل دارند، اما حافظ از غزل سعدی متأثر است و مضمون بیت دوم را از این بیت سعدی گرفته: «چندان‌که باز بیند دیدار آشنا را / یارب تو آشنا را مهلت ده و سلامت». خرمشاهی نیز غزل سعدی را در همین وزن و قافیه نشان می‌دهد.', ['ja:۱۴۲', 'kh:۱۲۶']),
 ('کیمیا، قارون، آینهٔ سکندر', 'خرمشاهی برای سه تعبیر این غزل یادداشت جداگانه دارد: «کیمیا» را با نقلی از نفائس‌الفنون آملی می‌گشاید، برای «قارون» روایت فرورفتن گنجش را تا تاریخ طبری پی می‌گیرد، و «آینهٔ سکندر» را با پیشینه‌اش در شاهنامه و اسکندرنامه‌ها می‌سنجد.', ['kh:۱۳۱–۱۳۵', 'kh:۱۵۱۸']),
 ('مثل‌ها و یک خوشنویسی کهن', 'هشت مدخل از فهرست مثل‌های دیوان به بیت‌های این غزل بازمی‌گردد. قطعه‌ای به خط سلطانعلی مشهدی با بیت‌هایی از این غزل در مرقّع بهرام‌میرزا (۹۵۱ ق) در کتابخانهٔ توپقاپی‌سرای استانبول نگه داشته می‌شود.', ['se:۲۶–۳۶', 'محمدحسن سمسار، «حافظ و هنر»، دائرةالمعارف بزرگ اسلامی، ج ۱۹، ۱۳۹۰، ص ۷۳۲']),
]

SHARH[7] = [
 ('صوفی و صافی', 'خرمشاهی در مطلع میان «صوفی»، «صافی» و «صفا» جناس شبه‌اشتقاق می‌بیند. به گفتهٔ او حافظ «عارف» را صوفی راستین می‌داند اما «صوفی» را «همواره به بدی یاد کرده» است، و این غزل از چند غزلی است که خطاب به صوفی‌اند و بیشتر بیت‌هایش وحدت موضوع دارد. سودی هم می‌گوید شاعران به صوفیان «زرّاق و مرایی» طعنه می‌زنند نه به صوفیان اهل مشرب.', ['kh:۱۳۷–۱۳۹', 'su:۵۸']),
 ('عنقا شکار کس نشود', 'سودی عنقا را جانان می‌داند که با فن و حیله به کسی التفات نمی‌کند، و از صحاح جوهری آن را مرغی «موجود الاسم و معدوم الجسم» می‌آورد. خرمشاهی سه معنای سیمرغ و عنقا را در شعر حافظ از هم جدا می‌کند و این بیت را در معنای سوم می‌نشاند: حقیقتی برتر حتی از انسان کامل؛ پیام غزل به صوفی این است که در هوای شکار سیمرغ، یعنی ذات حق، نباشد.', ['su:۵۹–۶۰', 'kh:۱۳۹–۱۴۱']),
 ('«آدم بهشت روضهٔ دارالسلام را»', 'در بیت ششم هر سه شرح «بهشت» را فعل می‌خوانند: «ب» تأکید و «هشت» ماضیِ «هشتن» یعنی رها کردن. خرمشاهی آن را ایهام تناسب می‌داند میان این فعل و بهشتی که در «روضهٔ دارالسلام» نهفته است.', ['su:۶۰–۶۱', 'kh:۱۴۷', 'ja:۱۵۳']),
 ('«مکن هنری» یا «بکن هنری»', 'ضبط قزوینی «مکن هنری» است و سودی، خانلری و بسیاری چاپ‌های دیگر «بکن هنری» دارند. خرمشاهی از سویی دوست دارد ضبط قزوینی را ارجح بدارد، اما می‌پذیرد که «هر دو اندیشه و هر دو قرائت در حافظ پیشینه و پشتوانه دارد». متن نیساری بر پایهٔ دست‌نویس‌های سدهٔ نهم «بکن هنری» است.', ['kh:۱۴۳–۱۴۴', 'ni:۳۷']),
 ('«شیخ جام» یا «شیخ خام»', 'خرمشاهی ضبط قزوینی «شیخ جام» را می‌پذیرد و گزارش می‌کند که خانلری نخست آن را تصحیف «شیخ خام» دانسته بود و بعد از این رأی بازگشت؛ غنی و سودی مراد را شیخ احمد جامی (نامقی) می‌دانند و همایی «جام می» با ایهامی به آن شیخ. جلالیان خوانش همایی را ارجح می‌داند.', ['kh:۱۴۷', 'su:۶۴', 'ja']),
 ('مثل‌ها', 'شش مدخل از فهرست مثل‌های دیوان به بیت‌های این غزل بازمی‌گردد، از جمله بیت سوم «عنقا شکار کس نشود دام بازچین».', ['se:۲۹–۳۰']),
]

SHARH[9] = [
 ('خرابات', 'بلندترین بحث خرمشاهی در این غزل بر سر «خرابات» بیت پنجم است. بهار این واژه را نخست در شعر سنایی دیده بود؛ خرمشاهی می‌نویسد «قول شادروان بهار درست نیست» و کاربرد آن را پیش‌تر در منوچهری، ناصرخسرو، خواجه عبدالله انصاری و غزالی نشان می‌دهد. در ریشهٔ واژه، میان «خرابه» (رأی قزوینی، فروزانفر و زریاب خویی) و «خورآباد» (رأی احمدعلی رجائی)، خود طرفدار رأی نخست است.', ['kh:۱۵۱–۱۵۳']),
 ('بلبل و مغبچه', 'خرمشاهی «بلبل» را در دیوان حافظ نماد سه چیز می‌داند: عاشقی و شیدایی، فصاحت و سخنوری، و خوش‌نوایی. دربارهٔ «مغبچه» می‌نویسد که «مغبچه و ترسابچه و صنم باده‌فروش همان ساقی حافظ است» که چون پیر مغان پایگاهی بلند در شعر او دارد.', ['kh:۱۴۹–۱۵۰']),
 ('سیه‌کاسه', '«سیه‌کاسه» در بیت هفتم به معنی بخیل و ممسک است (خرمشاهی به نقل از حواشی غنی)؛ هم خرمشاهی و هم جلالیان، جدا از هم، آن را با این بیت خاقانی سنجیده‌اند: «دهر سیه‌کاسه‌یی است ما همه مهمان او».', ['kh:۱۵۶', 'ja:۱۶۵']),
 ('رندی به جای ریا', 'حافظ در بیت پایانی رندی را بر ریا برمی‌گزیند. جلالیان غزل را سروده پس از رهایی تورانشاه، وزیر شاه شجاع، از زندان می‌داند و بیت پنجم و نهم را تلمیح به آیهٔ ۳۸ سورهٔ هود و آیهٔ ۵۴ سورهٔ یوسف. پیوند غزل با آن رویداد خوانش جلالیان است، نه گزارشی از خود دیوان.', ['kh:۱۵۷', 'ja:۱۶۵']),
 ('مثل‌ها', 'هشت مدخل از فهرست مثل‌های دیوان به بیت‌های این غزل بازمی‌گردد؛ بیت‌های ششم تا نهم هر یک سرآمد مدخلی‌اند.', ['se:۳۰–۳۲']),
]

SHARH[26] = [
 ('تبار یک مضمون', 'جلالیان از خانلری نقل می‌کند که این غزل در وزن و قافیه و مضمون «حاصل اندیشه و تصحیح و تکمیلِ یک عدّه از شعرا از قرن پنجم به بعد تا زمان حافظ» است. مضمون آن «اعتراض دلدارِ شوخِ مست به زهد و تقوای عاشقِ عارف» است که نخست در غزلی از سنایی دیده می‌شود و سپس انوری، ظهیر فاریابی، عطار و خواجو آن را پروراندند؛ خرمشاهی نیز چهار غزل از خواجو را در همین وزن و قافیه نشان می‌دهد.', ['ja:۲۴۸', 'kh:۲۲۱']),
 ('آواز حزین', 'به گفتهٔ جلالیان «آواز حزین» نام گونه‌ای آواز بوده: «نوعی از آواز نرم و گرم و گوش‌نواز… که در آن رگه‌یی از درد عشق نهفته» است؛ او از سعدی گواه می‌آورد: «چه خوش باشد آواز نرم حزین / به گوش حریفانِ مستِ صبوح». سودی همین مصرع را شاهد آورده است.', ['ja:۲۴۸', 'su:۲۰۰']),
 ('عهد الست و دُردکشی', 'سودی در بیت پنجم روی سخن را «زاهد خشکی» می‌داند که از دُردکشان خرده می‌گیرد، نه زاهد پاک، و «روز الست» را روز ازل که قضا و قدر تعیین می‌شود. خرمشاهی معنای بیت را چنین می‌دهد: «دُردکشی و رندی و شوریدگی، در علم الهی و عهد الست مقرر بوده است.» و بیت ششم را: آنچه ساقی ازل برای ما مقدر کرد شادمانه سر کشیدیم، یعنی «راضی به قضا و رضای او هستیم».', ['su:۲۰۲', 'kh:۲۲۳']),
 ('چند واژه', 'به گفتهٔ خرمشاهی: «افسوس» در بیت نخست دو معنا دارد، حسرت و ریشخند، و هر دو در حافظ سابقه دارد؛ «بادهٔ شبگیر» همان بادهٔ صبوح (سحرگاهی) است؛ «بادهٔ مست» یا بادهٔ مخصوص مستان است یا باده‌ای که خود مست است، برای مبالغه؛ «زلف گره‌گیر» به نقل از حواشی غنی زلفی است که چون بکشی صاف می‌ایستد و چون رها کنی باز گره می‌گیرد؛ و «خندهٔ جام» را صدای ریختن باده در پیاله می‌داند که به خنده‌ای کوتاه می‌ماند.', ['kh:۲۲۲–۲۲۴']),
 ('در هنر کتاب‌آرایی', 'در نسخه‌ای مصوّر از دیوان حافظ در کتابخانهٔ لیدن (۸۹۴ ق / ۱۴۸۹ م، مکتب شیراز دوم) نگاره‌ای بر پایهٔ این غزل هست.', ['محمدحسن سمسار، «حافظ و هنر»، دائرةالمعارف بزرگ اسلامی، ج ۱۹، ۱۳۹۰، ص ۷۲۸']),
]

SHARH[37] = [
 ('استقبال از اوحدی', 'چاپ قزوینی و غنی تنها یک پانویس بر این غزل دارد: «این غزل باستقبال غزلی از اوحدی است» با مطلع «مباش بندهٔ آن کز غم تو آزادست / غمش مخور که بغم خوردن تو دلشادست». خرمشاهی، به پشتوانهٔ مقالهٔ قزوینی در یادگار، مصرع «که این عجوزه عروس هزار داماد است» را تضمینی از اوحدی مراغه‌ای (م ۷۳۸ ق) می‌داند. او برای مطلع سرمشق‌هایی هم در سعدی و عطار نشان می‌دهد: «بیا که قبلهٔ ما گوشهٔ خراباتست / بیار باده که عاشق نه مرد طاماتست».', ['qg:۲۷', 'kh:۲۴۵', 'kh:۲۵۴', 'ja:۳۰۸']),
 ('«بیا» و «سخت سست»', 'خرمشاهی «بیا» را از واژه‌های کلیدی زیبای حافظ می‌داند که در این مطلع فعل آمدن نیست بلکه «آمیخته‌ایست از تشویق و موافقت‌طلبی»، چیزی چون «بدان، ببین، باور کن». میان «سخت» و «سست» ایهام تضاد هست، چون «سخت» هم ضدّ سست است و هم به معنی «بسیار»؛ سودی و جلالیان نیز «سخت سست» را «بسیار سست» می‌خوانند.', ['kh:۲۴۵–۲۴۶', 'su:۲۶۴', 'ja:۳۰۵']),
 ('سروش و شاهباز سدره‌نشین', 'به گفتهٔ سودی سخنان سروش عالم غیب از بیت «تو را ز کنگرهٔ عرش می‌زنند صفیر» آغاز می‌شود و پیامش این است که «مقام تو مقام ارواح قدس است». جلالیان «شاهباز سدره‌نشین» را انسان کامل می‌خواند و «عروس هزار داماد» را کنایه از بی‌وفایی دنیا؛ خرمشاهی یادآور می‌شود که «محنت‌آباد» کنایه از دنیاست و در شعر حافظ همین یک بار آمده است.', ['su:۲۶۵–۲۶۷', 'ja:۳۰۵–۳۰۹', 'kh:۲۵۰']),
 ('جبر و اختیار', 'درازترین بحث حافظ‌نامه در این غزل بر بیت «که بر من و تو در اختیار نگشادست» است. خرمشاهی نتیجه می‌گیرد: «اشعری‌گری حافظ اعتدالی است و به عناصری از اندیشه‌های کلامی اعتزالی ـ شیعی آمیخته است. لذا در دیوان حافظ… هم اقوالی حاکی از جبر هست و هم اقوالی حاکی از اختیار.» سودی کوتاه‌تر می‌گوید: «زمام اختیار را بدست من و تو نداده‌اند… این بیت سراسر پند است.»', ['kh:۲۵۲–۲۵۴', 'su:۲۶۹']),
 ('قبول خاطر', 'در مقطع («قبول خاطر و لطف سخن خدادادست»)، خرمشاهی معنای غنی را می‌پذیرد: «پسند خاطر مردم واقع شدن»، چون مراد خاطر دیگران است نه خاطر شاعر.', ['kh:۲۵۵']),
 ('مثل‌ها و خوشنویسی', 'سودی می‌نویسد بیت دوم «در میان اهل عرفان حکم ضرب‌المثل پیدا کرده است». در فهرست مثل‌های دیوان نُه مدخل به این غزل بازمی‌گردد. بیت‌هایی از آن به خط شیخ محمود پیر بوداقی، نوشته در همدان، در مرقّعی از یعقوب‌بیک آق‌قویونلو در توپقاپی‌سرای استانبول هست.', ['su:۲۶۵', 'se:۴۹–۵۱', 'zo:۷۱۷', 'محمدحسن سمسار، «حافظ و هنر»، دائرةالمعارف بزرگ اسلامی، ج ۱۹، ۱۳۹۰']),
]

SHARH[44] = [
 ('فتوای فقیه مست', 'سودی استدلال فقهی نهفته در بیت «فقیه مدرسه دی مست بود و فتوی داد…» را می‌گشاید: شراب‌خواری حق‌الله است و با توبه ساقط می‌شود، اما خوردن مال وقف حق مردم است و ساقط نمی‌شود؛ پس فتوای فقیه مست، با همهٔ تناقض ظاهری، بی‌پایه نیست. این بیت در فرهنگ‌های مثل به معنی نکوهش خوردن مال وقف آمده است.', ['su:۳۰۶', 'se:۳۲۸', 'zo:۱۷۳۷']),
 ('کشف کشّاف', 'به نقل خرمشاهی از یادداشت قزوینی، «کشف کشّاف» نام کتابی است: الکشف عن مشکلات الکشاف از سراج‌الدین عمر بن عبدالرحمن فارسی قزوینی (درگذشتهٔ ۷۴۵ ق)، شرحی بر کشّاف زمخشری که در جوانی حافظ در مدرسه‌ها خوانده می‌شد. دربارهٔ «دفتر اشعار» می‌نویسد مستبعد نیست حافظ جُنگ یا دفتری از شعر خود یا دیگران در دست داشته است.', ['kh:۲۷۵']),
 ('قلّاب', '«قلّاب» در بیت پایانی به معنی سکهٔ قلب و دغل‌کار است و تلفظش محل اختلاف: غنی آن را از عربیِ «قُلَّب» می‌داند، فرهنگ‌هایی چون غیاث‌اللغات و آنندراج «قَلّاب» به فتح ضبط کرده‌اند، و قزوینی و فروزانفر ضمّ را پذیرفته‌اند. خرمشاهی جانب ضمّ را می‌گیرد، به گواه «قُلّابی» در فارسی امروز. به آنان که گفته‌اند منطقاً باید «صرّاف شهر قلّاب است» می‌گفت، پاسخ می‌دهد: «این نه ضعف که قوت بیان حافظ را می‌رساند».', ['kh:۲۷۸–۲۸۰']),
 ('خوانش جلالیان', 'جلالیان مقطع را شکوهٔ حافظ از رقیبی می‌داند که در مجلسی ادبی، شاید در زمان شاه شجاع یا امیر مبارزالدین، شعر او را کم‌ارج شمرده؛ و تصریح می‌کند که نام آن شخص «بر ما معلوم نیست». کلارک نیز در ۱۸۹۱ «قلّاب» را شاعری فرودست دانسته که می‌کوشید شعر حافظ را از آنِ خود جا بزند.', ['ja:۳۳۴', 'H. W. Clarke, The Dīvān-i-Hāfiz, 1891, pp. 126–127']),
 ('مثل‌ها', 'سه بیت این غزل مثل شده است: «ببر ز خلق و چو عنقا قیاس کار بگیر» به معنی گوشه‌گیری، «بخواه دفتر اشعار و راه صحرا گیر»، و «فقیه مدرسه دی مست بود و فتوی داد».', ['se:۴۶–۴۷', 'se:۲۶۳–۲۶۴', 'se:۳۲۸']),
]

SHARH[115] = [
 ('درخت دوستی، نهال دشمنی', 'خرمشاهی ناهمسانی «درخت دوستی» و «نهال دشمنی» را در مطلع عمدی می‌داند: دوستی مهم‌تر و ریشه‌دارتر است و به درخت مانند شده، و جلوی دشمنی را باید از همان آغاز گرفت، پس نهال است. مطلع در فرهنگ‌های مثل به معنی «دعوت به دوستی و دشمنی نکردن» آمده است.', ['kh:۴۹۶', 'se:۱۰۲', 'zo:۹۶۸']),
 ('دردسر', 'به گفتهٔ خرمشاهی «دردسر» در بیت دوم ایهام دارد: هم زحمت و محنت، هم سردرد و رنج جسمانیِ خمار. او بازگفت غنی را می‌پسندد: «در مجلس بزم رندان موقر باش و با آنها با احترام سلوک کن… والّا پس از تمام شدن مستی، دردسر می‌کشی».', ['kh:۴۹۶–۴۹۷']),
 ('شب صحبت غنیمت دان', 'بیت سوم («شب صحبت غنیمت دان که بعد از روزگار ما / بسی گردش کند گردون بسی لیل و نهار آرد») پرنقل‌ترین بیت غزل است و در فرهنگ‌های مثل به معنی «قدر دانستن لحظاتی که با دوستان و یاران می‌گذرد» آمده است.', ['se:۱۰۲–۱۰۳', 'zo:۴۰۲']),
 ('عماری لیلی و هزارِ بلبل', 'سودی در بیت چهارم می‌نویسد «لیلی را به ماه و عماری وی را به گهواره تشبیه کرده» و جلالیان همین تشبیه را پیش‌تر در خاقانی می‌یابد. در بیت پنجم خرمشاهی میان «هزار» (بلبل) و «صد گل» ایهام تناسب می‌بیند و گواه‌هایی از خواجو و سلمان می‌آورد.', ['su:۷۲۵', 'ja:۶۵۹', 'kh:۴۹۷']),
 ('«از خدا خواهد» یا «ار خدا خواهد»', 'در بیت پایانی چاپ قزوینی و غنی «از خدا خواهد» دارد و در پانویس می‌گوید بعضی نسخه‌ها «ار» دارند. نیساری، سایه و خانلری «ار» خوانده‌اند و سودی «از»؛ جلالیان هر دو ضبط را پذیرفتنی می‌داند.', ['qg:۷۸', 'ni:۱۲۹', 'sa:۱۹۹', 'kh:۴۹۸', 'su:۷۲۷']),
]

SHARH[131] = [
 ('ترک فلک و هلال عید', 'سودی «ترک فلک» را آسمان در هیئت ترک یغماگر می‌گیرد و «هلال عید» را هلال شوّال. به گفتهٔ خرمشاهی «ترک فلک» اضافهٔ تشبیهی است، «فلکی که بی‌محابا حمله می‌آورد»، و «خوان روزه غارت کرد» یعنی «بساط روزه را درنوشت، یعنی ماه رمضان را سپری کرد».', ['su:۸۱۰', 'kh:۵۳۷']),
 ('«به دور قدح اشارت کرد»', 'غنی «دور قدح» را چرخاندن و به گردش انداختن قدح می‌دانست؛ خرمشاهی می‌نویسد «شادروان غنی در اینجا اشتباه کرده است» و معنای ظاهرتر را هلال نو می‌داند که به لبهٔ گرد قدح می‌ماند. با این همه خود او مصراع را دارای «ایهام دوگانه و حتی سه‌گانه» می‌شمارد و معنای غنی را یکی از آن‌ها می‌داند. سودی هم مصراع را به عمد دوپهلو می‌خواند: گردی قدح و گردش آن در مجلس.', ['kh:۵۳۸–۵۳۹', 'su:۸۱۰']),
 ('روزه و طنز', 'به گفتهٔ خرمشاهی «حافظ از روزه همانند نماز غالباً به‌طنز، و از پایان گرفتن ماه روزه به شادی یاد می‌کند» و معتقد است باید باطن عبادات را دریافت. در بیت پنجم، منشأ مضمون را با احتیاط سخن حلاج می‌داند: «رکعتانِ فی العشق لایصحّ وضوءُهما إلا بالدم».', ['kh:۵۳۷–۵۴۰']),
 ('جفتی همزاد با غزل ۱۳۲', 'این غزل و غزل ۱۳۲ وزن و قافیه و ردیف یکی دارند و مصراع «هلال عید به دور قدح اشارت کرد» در هر دو عیناً آمده است. در دست‌نویس‌های سدهٔ نهمِ نیساری، شش دست‌نویس از دوازده، بیت‌هایی از یکی را در دل دیگری دارند؛ سودی دو بیت از غزل ۱۳۲ را در این غزل آورده است. جلالیان هر دو را یک سروده می‌داند که خود شاعر بعدها بازسازی کرده است؛ خرمشاهی تنها خودتکراری حافظ را یادآور می‌شود.', ['qg:۸۹–۹۰', 'ni:۱۴۳–۱۴۴', 'su:۸۱۱–۸۱۸', 'ja', 'kh:۵۳۸']),
 ('شیخ شهر', 'سودی «شیخ شهر» را همان روحانی بلندپایهٔ شهر می‌گیرد و خرمشاهی کسی را نام نمی‌برد؛ جلالیان با تردید او را امیر مبارزالدین می‌داند.', ['su:۸۱۳', 'kh:۵۴۱', 'ja:۷۳۸']),
]

SHARH[143] = [
 ('جام جم: از کیخسرو تا دل عارف', 'به گفتهٔ خرمشاهی در شاهنامه جام گیتی‌نما از آنِ کیخسرو است و تا سدهٔ ششم به همین نام شهرت داشت؛ انتسابش به جمشید پس از آن پیدا شد، چون جم شهرت بیشتری داشت و روایت پیدایش شراب هم به او می‌رسید. «جام جم» در دیوان حافظ دو معنا دارد: جام می، و دل عارف که به تعبیر منوچهر مرتضوی «جلوه‌گاه جمال حقیقت» است.', ['kh:۵۶۴']),
 ('گوهری که نزد خود ما بود', 'خرمشاهی بیت نخست را چنین معنا می‌کند: دل رازجوی من جام جهان‌نما را از من می‌خواست، غافل از این‌که این جست‌وجو «تحصیل حاصل» است و خود او جام جهان‌نماست. در بیت دوم «گوهری» مفعول است نه فاعل، و «گمشدگان لب دریا» به استناد برهان قاطع کسانی‌اند که شنا نمی‌دانند و غرق می‌شوند. سودی هم می‌گوید همه این گوهر را دارند «منتها از مالکیت خود خبر ندارند»، و محمد معین غزل را در فصل «وصول» آورده است.', ['kh:۵۶۷', 'su:۸۶۶', 'محمد معین، حافظ شیرین‌سخن، ص ۱۵۷']),
 ('آن یار کزو گشت سر دار بلند', 'این بیت به حسین بن منصور حلاج اشاره دارد. خرمشاهی می‌نویسد حافظ «بر آن است که حلاج راست می‌گفت اما نمی‌بایست با نااهلان در میان می‌گذاشت»، و سخن خواجه عبدالله انصاری را گواه می‌آورد: «آنچه منصور حلاج گفت، مَن هم گفتم؛ او آشکارا گفت من نهفتم». در دانشنامهٔ ایرانیکا این بیت شناخته‌شده‌ترین بیت فارسی دانسته شده که به حلاج اشاره دارد.', ['kh:۵۷۰', 'su:۸۶۹', 'J. Mojaddedi, “Ḥallāj”, Encyclopaedia Iranica XI/6, 2003, pp. 589–592']),
 ('شعبدهٔ خویش یا شعبدهٔ عقل؟', 'قزوینی و غنی در بیت هفتم «این همه شعبدهٔ خویش» آورده‌اند و یادآور شده‌اند که نسخه‌های دیگر «عقل» دارند؛ نیساری و سودی «عقل» را برگزیده‌اند و سودی بیت را رویارویی عقل و عشق می‌خواند: «عشق غالبِ عقل است». خرمشاهی «عقل» را دستکاری کاتبان برای آسان‌کردن بیت می‌داند. در بیت ششم نیز بهار «خدایا» را به جای «خدا را» درست می‌داند، چون جای سوگند دادن نیست.', ['qg:۹۶', 'ni:۱۵۶', 'su:۸۷۰–۸۷۱', 'kh:۵۶۹']),
 ('جایگاه', 'آربری این غزل را «یکی از زیباترین شعرهای حافظ» خوانده و یادآور شده که متن آن به‌ویژه در ترتیب ابیات دگرسانی‌های چشمگیر دارد. در چاپ قزوینی و غنی این غزل شمارهٔ ۱۴۲ است و در متن گنجور ۱۴۳.', ['A. J. Arberry, Fifty Poems of Ḥāfiẓ, Cambridge, pp. 97–99, 153–154', 'qg:۹۶']),
]

SHARH[152] = [
 ('غزلی عرفانی از «غزل‌های عرشی»', 'درون‌مایهٔ این غزل تجلی حسن ازلی و پیدایش عشق در پی آن است؛ خرمشاهی آن را دربردارندهٔ «اشارات و آراء عرفانی مهمی» می‌داند. خرمشاهی و جلالیان آن را همراه «دوش دیدم که ملایک»، «دوش وقت سحر» و «سال‌ها دل طلب جام جم» از «غزل‌های عرشی» حافظ شمرده و این نام را به محمد معین نسبت داده‌اند؛ معین خود این تقسیم را از شیخ جابری انصاری نقل کرده و بر آن خرده گرفته است.', ['kh:۵۹۶', 'kh:۶۷۰', 'ja', 'محمد معین، حافظ شیرین‌سخن، ص ۳۷۵']),
 ('تجلی و گنج نهان', 'خرمشاهی «حسن» را حسن الهی و «سلسله‌جنبان آفرینش» می‌داند، «ازل» را «آغاز غیر زمانی»، و «تجلی» را از دشوارترین و مهم‌ترین اصطلاحات عرفان اسلامی. او بیت نخست را بر پایهٔ ابن عربی و حدیث «کنت کنزاً مخفیاً… فاحببت ان اعرف» می‌گشاید (حدیثی که اعتبار سندی‌اش از دیرباز محل بحث است). سودی ساده‌تر «تجلی» را «زیبائی خود را نشان دادن» معنا می‌کند. به گفتهٔ معین در جهان‌بینی حافظ «عشق علت ایجاد است نه عقل».', ['kh:۵۹۶–۶۰۲', 'su:۹۲۳', 'محمد معین، حافظ شیرین‌سخن، ص ۱۵۰']),
 ('فرشته عشق نداشت', 'خرمشاهی بیت دوم را چنین می‌گزارد: حسن الهی چون جلوه کرد در فرشتگان نگرفت، چون شایستهٔ امانت عشق نبودند، پس آتش غیرت به خرمن آدم زد. سودی هم می‌گوید «کیفیت عشق مخصوص انسان است» و جلالیان بیت را با بار امانت پیوند می‌دهد.', ['kh:۶۰۵', 'su:۹۲۴', 'ja']),
 ('مدعی کیست؟', 'در بیت چهارم («مدعی خواست که آید به تماشاگه راز») شارحان دو دسته‌اند: خرمشاهی و جلالیان «مدعی» را همان عقل نامحرم بیت سوم می‌دانند و «دست غیب» را غیرت الهی؛ سودی و چند پژوهشگر دیگر، به قرینهٔ داستان آفرینش آدم در مرصادالعباد، او را شیطان می‌گیرند. عقل و عشق در این غزل رویاروی‌اند: به تعبیر سودی «عقل و عشق باهم ضدند».', ['kh:۶۰۵', 'su:۹۲۵', 'ja']),
 ('جان علوی و طرب‌نامه', 'خرمشاهی «جان علوی» را جانی از عالم امر و ملکوت می‌داند که ظاهراً از فراز به فرود افتاد اما در واقع در دامن عشق الهی آویخت؛ مسعود معتمدی این تفسیر را نپذیرفته است. به گفتهٔ خرمشاهی «طرب‌نامه» تنها همین یک بار در شعر حافظ آمده است.', ['kh:۶۰۶–۶۰۷', 'su:۹۲۶']),
 ('خوانش عرفانی و نقد آن', 'خوانش عرفانی دیوان یکدست پذیرفته نیست: احسان یارشاطر کوشش برای تفسیر عرفانی سراسر دیوان را بی‌پشتوانه در خود آن می‌داند، و دخویه بروین در برابر یادآور می‌شود که از سدهٔ ششم مضمون‌های رندانه در شعر فارسی معنایی مجازی داشته‌اند. ترکیب «تماشاگه راز» از همین غزل عنوان کتاب مرتضی مطهری دربارهٔ عرفان حافظ شده است. بیت‌های سوم و چهارم در فرهنگ‌های مثل به معنی «راه نداشتن غیر عاشقان در حریم عشق» آمده‌اند.', ['E. Yarshater, “Hafez i. An Overview”, Encyclopaedia Iranica XI/5, 2002, pp. 461–465', 'J. T. P. de Bruijn, “Hafez iii. Hafez’s Poetic Art”, Encyclopaedia Iranica XI/5, 2002, pp. 469–474', 'se:۱۳۰–۱۳۱', 'zo:۶۸۹']),
]

SHARH[159] = [
 ('سنجش سکه', 'سراسر غزل بر تصویر سنجیدن سکه ساخته شده است. سودی «غش» را ناخالصی در برابر «صاف» می‌داند و «محک» را «سنگ سیاهی است که طلا و نقره را با آن آزمایش میکنند». سودی و خرمشاهی هر دو مطلع «نقدها را بود آیا که عیاری گیرند» را گواه همین مضمون می‌آورند.', ['su:۹۵۹–۹۶۰', 'kh:۶۱۹']),
 ('وجدنمایی صوفی', 'به گفتهٔ خرمشاهی بیت دوم از نفاق صوفی می‌گوید که بامداد از ذکر و دعای سحرگاهی سرمستی نشان می‌داد و «تواجد (وجدنمائی)» می‌کرد و شامگاه از بادهٔ انگوری مست می‌شد. جلالیان غزل را هشداری به مردم دربارهٔ «ظاهرالصلاحانِ نابکاری» می‌داند که زیر پوشش تصوف سر برآورده بودند.', ['kh:۶۱۸', 'ja:۸۷۴']),
 ('محک تجربه', 'خرمشاهی دربارهٔ بیت سوم («خوش بود گر محک تجربه آید به میان / تا سیه‌روی شود هر که در او غش باشد») می‌نویسد «این بیت در زبان فارسی، حکم مثل سائر را پیدا کرده است» و مضمونش احتمالاً از سخن منسوب به علی است: «عند الامتحان یُکرمُ الرّجلُ او یُهان». جلالیان بیت پنجم را به سبب بلاغتش مثل می‌شمارد.', ['kh:۶۱۹', 'ja:۸۷۵']),
 ('نقش بر آب', 'مصراع «خط ساقی گر از این گونه زند نقش بر آب» دو معنا دارد: کاری بی‌حاصل کردن، و نقشی که بر چهرهٔ روشن چون آب ساقی می‌افتد. جلالیان هر دو معنا را می‌آورد و خرمشاهی آن را ایهامی با همین دو سو می‌داند.', ['ja:۸۷۳', 'kh:۶۱۹']),
 ('چهار بیت مَثَل', 'چهار بیت از این غزل هفت‌بیتی ــ مطلع و بیت‌های سوم، پنجم و ششم ــ هر یک سرآمد مدخلی در فهرست مثل‌های دیوان‌اند، با کاربردهایی چون «باید با معیارهای تجربی تفاوت بین حق و باطل را متوجه شد» و «با راحت‌طلبی نمی‌توان به عشق واقعی رسید».', ['se:۱۳۴–۱۳۶']),
]

SHARH[164] = [
 ('بهار و جوانی دوبارهٔ جهان', 'سودی حاصل بیت نخست را چنین می‌آورد: جهان پیر از سختی زمستان رها شده و با آمدن بهار جوان گشته و باد بهاری همه‌جا را خوشبو خواهد کرد. خرمشاهی «عالم پیر» را تعبیری با پیشینه در شعر فارسی می‌داند که «فلک پیر» و «جهان پیر» هم گفته‌اند.', ['su:۹۸۵', 'kh:۶۳۰']),
 ('بلبل دادخواه', 'در بیت سوم سودی «سراپرده» را ویژهٔ پادشاهان می‌داند و بلبل را عاشقی که تا بارگاه گل فریادکنان می‌رود؛ خرمشاهی بلبل را «همچون دادخواهان» می‌بیند که تا بارگاه گل «فریادخواهی» می‌کند.', ['su:۹۸۶', 'kh:۶۳۱']),
 ('مسجد و خرابات', 'سودی بیت چهارم را ساده می‌خواند: اگر در مسجد به وعظ گوش کند، وقت رفتن به میخانه از دست می‌رود. خرمشاهی آن را نمونهٔ نگاه طنزآمیز حافظ به نهادهای شریعت و طریقت می‌داند، «یکی از اضلاع مهم طنز حافظ»، که به گفتهٔ او «حاکی از دردمندی و همدلی و اعتقاد است» و حربه‌ای برای دفع آفاتی چون ریاست.', ['su:۹۸۶', 'kh:۶۳۱']),
 ('ماه شعبان منه از دست قدح', 'خرمشاهی بیت ششم را به ماه شعبان، «آخرین فرصت سالانه شادخواران» پیش از رمضان، بازمی‌گرداند و میان «ماه» و «خورشید» (به معنی جام می) ایهام تناسب می‌بیند؛ سودی، خرمشاهی و جلالیان هر سه «خورشید» را استعاره از جام باده می‌گیرند. در بیت پنجم «ضمان» به معنی ضامن است.', ['kh:۶۳۲–۶۳۳', 'su:۹۸۷', 'ja:۸۹۹']),
 ('غزلی با بیت‌های مستقل', 'جلالیان این غزل را از دسته‌ای می‌داند که حافظ در آن از ایهام و مضامین عرفانی بهره نمی‌برد و حاصلش غزلی است با «ابیات مستقل و مضامین متنوّع» که «شور و شوق و طنز و اندرز» در آن آمیخته است. بیت پنجم («ای دل ار عشرت امروز به فردا فکنی») در فهرست مثل‌ها به معنی «لذت بردن از همهٔ لحظات کوتاه عمر» آمده است.', ['ja:۹۰۰', 'se:۱۴۱–۱۴۲']),
]

SHARH[183] = [
 ('غزلی واقعه‌گویانه', 'خرمشاهی این غزل را «واقعه‌گویانه» می‌خواند که «بیانگر یکی از احوال عرفانی و تجارب روحی حافظ است»؛ او و جلالیان آن را از «غزل‌های عرشی» می‌شمارند (تقسیمی که معین از شیخ جابری انصاری نقل و نقد کرده است). جلالیان «وقت سحر» را اصطلاحی صوفیانه می‌داند: «وقت حالی است که در سرِ سالک پدید آید… و سحر، زمان تلألؤ انوار حقّ است».', ['kh:۶۷۰', 'ja', 'محمد معین، حافظ شیرین‌سخن، ص ۳۷۵']),
 ('شب قدر و تازه برات', 'خرمشاهی مفصل‌ترین یادداشتش را به «شب قدر» داده و بیت سوم را چنین معنا می‌کند: «شب قدر من سحر مبارکی بود که برات آزادی از بار گناهان به من داده شد و احساس بخشودگی به من دست داد». «برات» سندی است که بر پایه‌اش حواله‌ای پرداخت می‌شود، و در روایتی شب قدر همان «لیلةالبراءة» دانسته شده است.', ['kh:۶۷۲']),
 ('پرتو ذات', 'بیت دوم به تجلی اشاره دارد: جلالیان یادآور می‌شود که تجلی در اصطلاح صوفیان دو گونه است، تجلی ذات و تجلی صفات، و مصرع دوم را چنین معنا می‌کند: «با مشاهدهٔ جمال یار، عشق را به من هدیه کردند». خرمشاهی «پرتو ذات» را تجلی ذاتی می‌خواند و به شرح غزل «در ازل پرتو حسنت» ارجاع می‌دهد.', ['ja', 'kh:۶۷۰']),
 ('صبر و شاخ نبات', 'به نقل خرمشاهی از امیرحسن یزدگردی، «صبر» در بیت هفتم با «شهد» و «شکر» و «شاخ نبات» ایهام تضاد دارد، چون صبر هم شکیبایی است و هم نام دارویی تلخ. سودی می‌نویسد «مراد از شاخ نبات قلم می‌باشد» و شاید به تشبیه، جانان؛ جلالیان نیز آن را قلم شاعر می‌داند، چون از ساقهٔ نی هم برای شیرینی و هم برای قلم بهره می‌بردند.', ['kh:۶۷۳', 'su:۱۰۷۷', 'ja']),
 ('خوانشی دیگر، و یک افسانه', 'سودی غزل را غیرعرفانی می‌خواند: جانان سحرگاهی به منزل خواجه آمده و «آب حیات» آب وصال است و «ظلمت شب» ظلمت هجران. در فرهنگ عامه این غزل به افسانه‌ای پیوند خورده که حافظ پس از شب‌زنده‌داری در خواب یا مکاشفه صاحب قریحهٔ شعر شد و «شاخ نبات» نام معشوق اوست؛ معین این داستان را رد می‌کند: به خواب صاحب علم و قریحه شدن «نه‌تنها از نظر علمی قابل قبول نیست… بلکه جنبهٔ تاریخی آن نیز مردود است».', ['su:۱۰۷۴', 'محمد معین، حافظ شیرین‌سخن، ص ۱۰۱–۱۰۲', 'عبدالعلی دستغیب، حافظ‌شناخت، علم، ص ۳۹۱–۳۹۲']),
]

SHARH[184] = [
 ('روایت آفرینش آدم', 'غزل با روایتی از آفرینش آدم آغاز می‌شود. به گفتهٔ خرمشاهی «به‌احتمال بسیار یکی از منابع فکری این غزل… فصل چهارم مرصادالعباد» نجم‌الدین رازی است، و معنای سه بیت نخست این است: در مشاهده‌ای دیشب دریافتم که خمیرمایهٔ اصلی انسان عشق است. آنه‌ماری شیمل تأکید می‌کند که «دوش» اینجا گزارش خواب نیست و به بزم میثاق ازلی اشاره دارد.', ['kh:۶۷۶–۶۷۸', 'A. Schimmel, A Two-Colored Brocade, p. 58']),
 ('گل آدم و پیمانه', 'در نقش فرشتگان اختلاف هست: خطیب رهبر «به پیمانه زدند» را «در قالب بشری ریختند» معنا کرده و غلامحسین یوسفی «گل وجود آدم را با شراب عشق آمیختند». سودی بیت نخست را ادعای برتری فرشتگان می‌داند که آدم را تحقیر کردند.', ['امیرحسین ماحوزی و همکاران، «نقد انگارهٔ بی‌بهرگی فرشته از عشق در شعر حافظ»', 'su:۱۰۸۰']),
 ('بار امانت و «دیوانه»', 'بیت سوم به آیهٔ امانت (احزاب، ۷۲) اشاره دارد. خرمشاهی «دیوانه» را ترجمهٔ «ظلوم و جهول» در همان آیه می‌داند؛ سودی می‌گوید افلاک و عناصر با همهٔ عظمت بار عشق را نپذیرفتند اما انسان پذیرفت. نجیب مایل هروی «بار امانت» را ودیعه‌ای الهی می‌داند که آدمی با آن به شناخت و دوستی خداوند می‌رسد.', ['kh:۶۷۸', 'su:۱۰۸۱', 'نجیب مایل هروی، «بار امانت»، دائرةالمعارف بزرگ اسلامی، ج ۱۱']),
 ('جنگ هفتاد و دو ملت', 'بیت چهارم از مشهورترین بیت‌های دیوان است. خرمشاهی یادآور می‌شود که حافظ «قائل به عدد هفتاد و دو بوده است، نه هفتاد و سه؛ یعنی به فرقهٔ ناجیه معتقد نبوده»، و معنا را این می‌داند که جنگ فرقه‌ها را «امری ناگزیر… و در عین حال معصومانه و کودکانه بدان؛ لذا معذورشان بدار». سودی دلیل چنددستگی را آن می‌داند که هیچ گروه «بحق الیقین نرسیده‌اند». شیمل این مصرع را ضرب‌المثل‌شده می‌خواند.', ['kh:۶۸۲', 'su:۱۰۸۲', 'A. Schimmel, A Two-Colored Brocade, p. 260', 'se:۱۵۳–۱۵۵', 'zo:۸۰۳']),
 ('شرح دوانی', 'جلال‌الدین دوانی (درگذشتهٔ ۹۰۸ ق) رساله‌ای جداگانه در شرح همین غزل نوشت و آن را، به گفتهٔ خرمشاهی، «به‌دو طریقهٔ حکمی و عرفانی، به مشرب ابن عربی» شرح کرد. کارل ارنست که این رساله را بررسی کرده، نتیجه می‌گیرد که چندگانگی تفسیرها از یک بیت حافظ در آن روزگار امری عادی شمرده می‌شد.', ['kh:۶۷۶', 'C. W. Ernst, in L. Lewisohn (ed.), Hafiz and the Religion of Love in Classical Persian Poetry, I.B. Tauris, 2010, pp. 197–210']),
]

SHARH[407] = [
 ('مزرع سبز فلک و داس مه نو', 'خرمشاهی هر دو ترکیب را اضافهٔ تشبیهی می‌داند و یادآور می‌شود که «قدما بین رنگ سبز و آبی خلط می‌کرده‌اند به‌طوری که آسمان یا دریا را اخضر (= سبز) می‌نامیدند». تشبیه ماه نو به داس پیشینه دارد؛ از جمله در انوری: «گاو گردون هرگز اندر خرمن عمرت مباد / تا مه نو کشت‌زار آسمان را هست داس». سودی می‌گوید شاعر با دیدن هلال به یاد «عملم در دنیا و جزا و پاداشم در آخرت» افتاد.', ['kh:۱۱۲۰', 'su:۲۲۰۷']),
 ('خورشید دمید', 'خرمشاهی «خورشید دمید» را چنین معنا می‌کند: «دیرگاه شد. وقت دعای سحر و مظان استجابت دعا را از دست دادی»، و «سابقه» را «سابقهٔ لطف و رحمت ازلی خداوند» می‌داند.', ['kh:۱۱۲۲', 'su:۲۲۰۸']),
 ('اختر شب‌دزد', 'سودی «اختر شب‌دزد» را کنایه از دنیا می‌گیرد: «به سازگاری و مساعدت چند روزهٔ فلک اعتماد مکن، زیرا عاقبت هلاکت می‌کند». به گفتهٔ خرمشاهی برخی نسخه‌ها «شبگرد» دارند.', ['su:۲۲۰۹', 'kh:۱۱۲۱']),
 ('گوشوار و بیدق', 'به گفتهٔ خرمشاهی بیت «گوشوار زر و لعل» «ایهام و ظرایف پیچ‌درپیچی دارد»: «گران داشتن گوش» هم بار سنگین بر گوش نهادن است و هم کر کردن آن. «بیدق راندن» اصطلاح شطرنج است، راندن پیاده به جلو، کنایه از «حداقل حرکت»: خال تو با کمترین جلوه بر ماه و خورشید پیشی گرفت.', ['kh:۱۱۲۲–۱۱۲۳', 'su:۲۲۱۱']),
 ('مثل‌ها', 'سه بیت این غزل مثل شده است: مطلع به معنی دیدن نتیجهٔ کردار، «تکیه بر اختر شب‌دزد مکن» به معنی بی‌رحمی روزگار، و «آسمان گو مفروش این عظمت».', ['se:۲۹۸–۳۰۱', 'se:۳۸–۳۹', 'zo:۴۴۴', 'zo:۷۰۴']),
]

SHARH[35] = [
 ('حافظ یا سلمان ساوجی؟', 'به گفتهٔ خرمشاهی این غزل در یکی از مثنوی‌های سلمان ساوجی (جمشید و خورشید) به نام سلمان هم ثبت شده است، «ولی سبک و سند (جمیع نسخ معتبر دیوان حافظ) حاکیست که این غزل از حافظ است». او یادآور می‌شود که غزل‌های هم‌وزن و هم‌قافیه در سلمان و حافظ بسیار است و چون هم‌روزگار بودند، نمی‌توان گفت کدام نخست سروده است. این غزل در تصحیح نیساری از دست‌نویس‌های سدهٔ نهم نیامده است.', ['kh:۲۴۱', 'kh:۸۰', 'ni:۵۶۴–۵۶۶']),
 ('نهیب به واعظ', 'سودی مطلع را سرزنشی بی‌پرده می‌خواند: «بتو چه رسیده است که اینهمه ملامتم میکنی… از عاشقی و رسوائی من بتو چه زیانی میرسد». خرمشاهی در «تو را چه افتادست» دو معنا می‌بیند: پرسش انکاری («تو دلی نداری که از ره بیفتد») و «برای تو چه حادثه‌ای رخ داده است؟»؛ او ضبط «دل از کف» را رد می‌کند و «از ره افتادن» را گمراه یا وامانده شدن می‌داند.', ['su:۲۵۵', 'kh:۲۴۱–۲۴۲']),
 ('میانی که از هیچ آفریده شده', 'در بیت دوم، به گفتهٔ خرمشاهی «آفریده است از هیچ» هم باریکی بی‌جسم کمر یار است و هم «یادآور اصطلاح کلامی خلق از عدم»؛ و مبالغه در باریکی کمر تا حد هیچ پیشینه‌ای کهن دارد، از جمله در عطار: «آن دهان نیست که تنگ شکرست / و آن میان نیست که موئی دگرست».', ['kh:۲۴۲–۲۴۳', 'su:۲۵۵–۲۵۶']),
 ('کام و نای', 'سودی و خرمشاهی هر دو در «به کام تا نرساند مرا لبش چون نای» ایهام می‌بینند: «کام» هم آرزوست و هم دهان. به تعبیر خرمشاهی: تا لب مرا به لب خود نرساند، نصیحت همهٔ عالم مانند نی در گوش من باد است؛ اما این باد برای حافظ مجازی (هیچ و پوچ) است و برای نی حقیقی.', ['su:۲۵۷', 'kh:۲۴۳']),
 ('هشت خلد، و «این از آن دادست»', 'سودی «گدا» را در بیت چهارم تهیدست می‌داند نه دریوزه‌گر؛ خرمشاهی هشت بهشت را از غیاث‌اللغات برمی‌شمارد. در بیت ششم «داد» به گفتهٔ خرمشاهی ایهام دارد: هم «داده است» و هم «داد» به معنی عدل، که با «جور» و «بیداد» ایهام تضاد می‌سازد؛ سودی نیز هر دو معنا را می‌پذیرد.', ['su:۲۵۶–۲۵۷', 'kh:۲۴۳–۲۴۴']),
 ('فسانه و فسون', 'خرمشاهی همین مقطع را گواه می‌آورد که فعلِ افسون «دمیدن» است نه «دادن»، و بیتی هم‌زبان از سلمان ساوجی را کنارش می‌گذارد: «واعظ برو فسانه مخوان و فسون مدم / کی درد عاشقی به فسان و فسون رود». مطلع غزل در فهرست مثل‌ها به این معناست که نباید بر کسی که رنج می‌کشد خرده گرفت.', ['kh:۳۵۶–۳۵۷', 'su:۲۵۸', 'se:۴۹']),
]

SHARH[19] = [
 ('وادی ایمن و آتش طور', 'سودی بیت دوم («شب تار است و ره وادی ایمن در پیش / آتش طور کجا، موعد دیدار کجاست») را تلمیح به سرگذشت موسی می‌داند و داستان گریز او از فرعون و رفتنش به مدین را باز می‌گوید. خرمشاهی بلندترین بخش مدخلش را به «وادی ایمن» و «آتش طور» می‌دهد، با ارجاع به قصص‌الانبیاء نیشابوری و آیه‌های قرآن.', ['su:۱۶۶–۱۶۷', 'kh:۱۸۶–۱۸۷']),
 ('خرابی و اشارت', 'به گفتهٔ خرمشاهی «خرابی» در بیت سوم ایهام دارد: هم مستی و بی‌خبری و هم ویرانی و نابودی، و مصرع نخستش از آیهٔ «کل شیءٍ هالک» برگرفته است. دربارهٔ «اشارت» در بیت چهارم می‌گوید حافظ به رمز سخن می‌گوید هم تا راز از نامحرمان پوشیده بماند و هم چون «دقایق و رقایق تصوف در ظرف زبان متعارف… نمی‌گنجد».', ['kh:۱۸۹–۱۹۰']),
 ('مهیّا یا مهنّا', 'بر سر واژهٔ پایانی بیت هشتم اختلافی مشهور هست: قزوینی، سودی و خانلری «مهیّا» دارند، اما خرمشاهی «مهنّا» را ترجیح می‌دهد، چون حافظ «تا این میزان عجز و کمبود لغوی ندارد که مهیا را دو بار در دو مصراع به کار برد»، میان آن دو جناس هست، و «عیش مهنّا» ترکیبی جاافتاده بوده است؛ از جمله در سعدی: «تا مهیا نبود عیش مهنّا نرویم». حافظ به سعی سایه نیز «مهنّا» دارد.', ['kh:۱۹۱–۱۹۲', 'sa:۹۸']),
 ('بگویید، بپرسید، مپرسید', 'مصرعی از بیت سوم در منابع پنج صورت دارد: «بگوئید» در چاپ قزوینی و غنی، «مپرسید» در سایه و دو دست‌نویس سدهٔ نهم، «نپرسند» در متن نیساری و «بپرسید» در سودی. سودی نوشته بود «مپرسید» را در هیچ نسخه‌ای نیافته است، اما دستگاه نیساری آن را در دو دست‌نویس گزارش می‌کند.', ['qg:۱۵', 'ni:۴۸', 'su:۱۶۸', 'sa:۹۸', 'kh:۱۸۶']),
 ('خوانش جلالیان', 'جلالیان غزل را از سال ۷۵۴، روزگار دربه‌دری شاه شیخ ابواسحاق پس از محاصرهٔ شیراز به دست امیر مبارزالدین، می‌داند؛ بر این خوانش مطلع خبر آن شاه را از نسیم سحر می‌پرسد. این خوانش اوست، نه گزارشی از خود دیوان. نُه مدخل از فهرست مثل‌های دیوان به بیت‌های این غزل بازمی‌گردد.', ['ja:۲۱۴', 'se:۳۵–۳۷']),
]

SHARH[77] = [
 ('دو «برگ» در مطلع', 'به گفتهٔ خرمشاهی «برگ» در شعر حافظ سه معنا دارد: برگ گیاه، توان و ساز و برگ، و میل و آرزو؛ و دو «برگ» مطلع یکی نیستند: «برگ گلی» برگ گیاه است و «برگ و نوا» در مصرع دوم به معنای ساز و توان.', ['kh:۳۸۴']),
 ('شیخ صنعان و قلندر', 'خرمشاهی شیخ صنعان را «مظهر لاابالیگری و ملامتیگری و پاکباختگی در عشق و طریقت» می‌داند و می‌گوید «شیرین قلندر» بیت بعد هم شاید اشاره به او باشد؛ سودی خلاصهٔ داستانش را می‌آورد و خواننده را به منطق‌الطیر عطار می‌فرستد. برای «قلندر» خرمشاهی سه ریشه‌شناسی می‌آورد و از معین نقل می‌کند که «منشأ قلندر هنوز روشن نیست».', ['kh:۳۸۵–۳۸۸', 'su:۴۸۶–۴۸۸']),
 ('زنّار و تسبیح', 'خرمشاهی یادآور می‌شود که حافظ زنّار را در برابر تسبیح و نشانهٔ کفر می‌آورد، حال آن‌که نشان اهل کتاب است؛ و این سنتی در شعر فارسی است که آنچه به اهل کتاب مربوط است را با کفر یکی می‌گیرد، چنان‌که «کنشت» را نه عبادتگاه یهود که بتکده می‌انگارند. بیت ششم در فهرست مثل‌ها به این معناست که «نمی‌توان هم عاشقی کرد و هم در پی حفظ آبرو بود».', ['kh:۳۸۹', 'se:۸۳', 'zo:۱۵۱۲']),
 ('جنات تجری تحتها الانهار', 'بیت پایانی عبارتی قرآنی را در خود دارد. سودی گزارش می‌کند که بر حافظ خرده گرفته‌اند که رودها زیر قصر جاری‌اند نه «زیر بام قصر»، و پاسخ می‌دهد که بیت اقتباس است و تنوین به ضرورت وزن افتاده. سودی و خرمشاهی، جدا از هم، یادآور می‌شوند که در قرآن جز یک جا (آخر سورهٔ توبه) همه‌جا «من تحتها الانهار» آمده است. خرمشاهی خوانشی را که «چشم حافظ» را فاعل همهٔ تصویرها می‌گیرد نمی‌پذیرد، چون بیشترینهٔ لطف بیت را از میان می‌برد.', ['su:۴۸۹', 'kh:۳۸۹–۳۹۰']),
]

SHARH[245] = [
 ('طوطی گویای اسرار کیست؟', 'سودی «طوطی» را خطاب شاعر به جان یا به قلم خود می‌داند: اگر خود شاعر مراد باشد «منقار» کنایه از دهان است و اگر قلم، نوک قلم به منقار مانند شده؛ کلارک، پین و بیکنل نیز آن را خود شاعر یا پیر راه می‌خوانند. جلالیان، تنها در میان این منابع، سراسر غزل را وصف مستی حشیش و «طوطی» را خود حشیش می‌داند و می‌پذیرد که این رأی خوانندگان را شگفت‌زده می‌کند.', ['su:۱۴۷۳', 'ja:۱۳۰۴–۱۳۰۹', 'H. W. Clarke, The Dīvān-i-Hāfiz, 1891, p. 495']),
 ('منصور کیست؟', 'در بیت یازدهم («به یمن دولت منصور شاهی») سودی، کلارک و بیکنل «منصور» را صفت شیخ ابواسحاق، ممدوح حافظ، می‌گیرند؛ خرمشاهی و جلالیان او را شاه منصور، واپسین فرمانروای آل مظفر، می‌دانند. سودی همین خوانش دوم را پنج سده پیش‌تر رد کرده بود. ضبط نسخه‌ها هم یکی نیست: متن نیساری «به یمن رایت منصور شاهی» دارد و قزوینی در پانویس ضبطی دیگر با نام فرمانروایی دیگر آورده است.', ['su:۱۴۷۹', 'kh:۱۰۷۷', 'ja', 'ni:۲۵۴', 'qg:۱۶۵']),
 ('خضر و سکندر، و بت چینی', 'سودی بیت هفتم را به داستان جست‌وجوی آب حیات به دست خضر و اسکندر بازمی‌گرداند: این بخشش با زر و زور به دست نمی‌آید و خدایی است. جلالیان «بت چینی» را کنایه از تیمور می‌داند و بیکنل آن را خنیاگر یا محبوبی از ترکستان چین.', ['su:۱۴۷۶', 'ja:۱۳۰۵']),
 ('قافیهٔ تکراری و مثل‌ها', 'خرمشاهی این غزل دوازده‌بیتی را در فهرست غزل‌های دارای قافیهٔ تکراری آورده است، چون «نگه دار» در دو بیت قافیه شده. در فهرست مثل‌های دیوان، بیت‌های سوم، هفتم و هشتم این غزل هر یک خود مَثَل شده‌اند.', ['kh:۸۴۴', 'se:۱۹۸–۱۹۹', 'se:۳۱۱']),
]
